class Solution {
    private int[][][] memo;

    public int removeBoxes(int[] boxes) {
        memo = new int[boxes.length][boxes.length][boxes.length + 1];
        return dp(boxes, 0, boxes.length - 1, 0);
    }

    private int dp(int[] boxes, int left, int right, int carry) {
        if (left > right) return 0;
        if (memo[left][right][carry] != 0) return memo[left][right][carry];

        int originalLeft = left;
        int originalCarry = carry;
        while (left + 1 <= right && boxes[left + 1] == boxes[left]) {
            left++;
            carry++;
        }

        int best = (carry + 1) * (carry + 1) + dp(boxes, left + 1, right, 0);
        for (int middle = left + 1; middle <= right; middle++) {
            if (boxes[middle] == boxes[left]) {
                best = Math.max(best,
                        dp(boxes, left + 1, middle - 1, 0) + dp(boxes, middle, right, carry + 1));
            }
        }
        memo[originalLeft][right][originalCarry] = best;
        return best;
    }
}

class Solution {
    private int[][][] memo;
    private int[] boxes;

    public int removeBoxes(int[] boxes) {
        this.boxes = boxes;
        memo = new int[boxes.length][boxes.length][boxes.length + 1];
        return dp(0, boxes.length - 1, 0);
    }

    private int dp(int left, int right, int carry) {
        if (left > right) return 0;
        if (memo[left][right][carry] != 0) return memo[left][right][carry];

        int originalRight = right;
        int originalCarry = carry;
        while (right > left && boxes[right] == boxes[right - 1]) {
            right--;
            carry++;
        }

        int best = dp(left, right - 1, 0) + (carry + 1) * (carry + 1);
        for (int mid = left; mid < right; mid++) {
            if (boxes[mid] == boxes[right]) {
                best = Math.max(best, dp(left, mid, carry + 1) + dp(mid + 1, right - 1, 0));
            }
        }
        memo[left][originalRight][originalCarry] = best;
        return best;
    }
}

class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][][] dp = new int[n][n][n + 2];
        for (int length = 1; length <= n; length++) {
            for (int left = 0; left + length - 1 < n; left++) {
                int right = left + length - 1;
                for (int carry = n; carry >= 0; carry--) {
                    int best = (carry + 1) * (carry + 1);
                    if (left + 1 <= right) {
                        best += dp[left + 1][right][0];
                    }
                    if (carry + 1 <= n) {
                        for (int middle = left + 1; middle <= right; middle++) {
                            if (boxes[middle] == boxes[left]) {
                                int middleScore = middle == left + 1 ? 0 : dp[left + 1][middle - 1][0];
                                best = Math.max(best, middleScore + dp[middle][right][carry + 1]);
                            }
                        }
                    }
                    dp[left][right][carry] = best;
                }
            }
        }
        return dp[0][n - 1][0];
    }
}

class Solution {
    private int[] colors;
    private int[] counts;
    private int[][][] memo;

    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        colors = new int[n];
        counts = new int[n];
        int groups = 0;
        for (int box : boxes) {
            if (groups > 0 && colors[groups - 1] == box) {
                counts[groups - 1]++;
            } else {
                colors[groups] = box;
                counts[groups] = 1;
                groups++;
            }
        }
        memo = new int[groups][groups][n + 1];
        return solve(0, groups - 1, 0);
    }

    private int solve(int left, int right, int carry) {
        if (left > right) return 0;
        if (memo[left][right][carry] != 0) return memo[left][right][carry];

        int mergedCount = counts[right] + carry;
        int best = solve(left, right - 1, 0) + mergedCount * mergedCount;
        for (int mid = left; mid < right; mid++) {
            if (colors[mid] == colors[right]) {
                best = Math.max(best,
                        solve(left, mid, carry + counts[right]) + solve(mid + 1, right - 1, 0));
            }
        }
        memo[left][right][carry] = best;
        return best;
    }
}

import java.util.*;

class Solution {
    private int[][][] memo;
    private Map<Integer, List<Integer>> positions;

    public int removeBoxes(int[] boxes) {
        memo = new int[boxes.length][boxes.length][boxes.length + 1];
        positions = new HashMap<>();
        for (int i = 0; i < boxes.length; i++) {
            positions.computeIfAbsent(boxes[i], ignored -> new ArrayList<>()).add(i);
        }
        return score(boxes, 0, boxes.length - 1, 0);
    }

    private int score(int[] boxes, int left, int right, int carry) {
        if (left > right) return 0;
        if (memo[left][right][carry] != 0) return memo[left][right][carry];

        int originalLeft = left;
        int originalCarry = carry;
        while (left + 1 <= right && boxes[left + 1] == boxes[left]) {
            left++;
            carry++;
        }

        int best = (carry + 1) * (carry + 1) + score(boxes, left + 1, right, 0);
        for (int middle : positions.get(boxes[left])) {
            if (middle <= left || middle > right) continue;
            best = Math.max(best,
                    score(boxes, left + 1, middle - 1, 0) + score(boxes, middle, right, carry + 1));
        }
        memo[originalLeft][right][originalCarry] = best;
        return best;
    }
}
